   142→  // ── SCHEDULED CLEANUP ──────────────────────────────────────────────────────
   143→  // Runs on fixed dates every month: 7, 14, 21, 28, and last day of month
   144→  // (e.g. 30th/31st for long months). On each cleanup day ALL request_logs are
   145→  // exported to Telegram as CSV + summary, then deleted from the DB.
   146→  // A lastCleanupDate guard ensures it runs only once per day even if the
   147→  // server restarts multiple times.
   148→
   149→  let lastCleanupDate: string | null = null;
   150→
   151→  const todayIST = () => {
   152→    return new Date().toLocaleDateString("en-CA", { timeZone: "Asia/Kolkata" }); // "YYYY-MM-DD"
   153→  };
   154→
   155→  const isCleanupDay = () => {
   156→    const now = new Date(new Date().toLocaleString("en-US", { timeZone: "Asia/Kolkata" }));
   157→    const day = now.getDate();
   158→    const lastDay = new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate();
   159→    const cleanupDays = new Set([7, 14, 21, 28]);
   160→    if (lastDay > 28) cleanupDays.add(lastDay); // e.g. 29 for leap-Feb, 30/31 for other months
   161→    return cleanupDays.has(day);
   162→  };
   163→
   164→  const runScheduledCleanup = async () => {
   165→    const today = todayIST();
   166→    if (!isCleanupDay() || lastCleanupDate === today) return;
   167→
   168→    lastCleanupDate = today; // lock immediately to prevent double-run
   169→    log(`[cleanup] Scheduled cleanup day! Starting export & purge for ${today}...`, "cleanup");
   170→
   171→    try {
   172→      // 1. Fetch ALL current request_logs before deletion
   173→      const logsToDelete = await storage.fetchLogsBeforeCleanup(0);
   174→
   175→      // 2. Send CSV + summary to Telegram admins BEFORE deleting
   176→      if (logsToDelete.length > 0) {
   177→        log(`[cleanup] Sending ${logsToDelete.length} records to Telegram admins...`, "cleanup");
   178→        await sendCleanupReport(logsToDelete);
   179→      }
   180→
   181→      // 3. Delete ALL request_logs
   182→      const result = await storage.cleanupAllRequestLogs();
   183→      log(`[cleanup] Purged ${result.deletedLogs} request_logs on ${today}`, "cleanup");
   184→    } catch (err) {
   185→      lastCleanupDate = null; // reset so it can retry this hour
   186→      log(`[cleanup] Error during scheduled cleanup: ${err}`, "cleanup");
   187→    }
   188→  };
   189→
   190→  // Check every hour whether today is a cleanup day
   191→  setInterval(runScheduledCleanup, 60 * 60 * 1000);
   192→  // Also check shortly after startup (in case server was down on a cleanup day)
   193→  setTimeout(runScheduledCleanup, 15_000);
   194→})();
